    /* Decodes an even-length hex literal into raw bytes. */
    std::vector<uint8_t> fromHex(const char* hex) {
        auto nibble = [](char c) -> int {
            if (c >= '0' && c <= '9') { return c - '0'; }
            if (c >= 'a' && c <= 'f') { return c - 'a' + 10; }
            if (c >= 'A' && c <= 'F') { return c - 'A' + 10; }
            return -1;
        };

        std::vector<uint8_t> out;
        for (const char* p = hex; *p && *(p + 1); p += 2) {
            out.push_back(uint8_t((nibble(p[0]) << 4) | nibble(p[1])));
        }
        return out;
    }

    SReadOnlyByteSpan toSpan(const std::vector<uint8_t>& bytes) {
        return bytes.empty()
            ? SReadOnlyByteSpan(nullptr, 0)
            : SReadOnlyByteSpan(bytes.data(), bytes.size());
    }

    SByteSpan toMutableSpan(std::vector<uint8_t>& bytes) {
        return bytes.empty() ? SByteSpan(nullptr, 0) : SByteSpan(bytes.data(), bytes.size());
    }

    struct SigVerVector {
        const char* name;
        MlDsaParams params;
        bool external;
        const char* context;
        const char* message;
        const char* pk;
        const char* signature;
        bool expected;
    };

